import React, { useEffect, useState } from 'react';
import { approvalsApi } from '../../../services/api';
import PageHeader from '../../../components/shared/PageHeader';

export default function NGOApprovalsPage() {
  const [ngoId, setNgoId] = useState(window.localStorage.getItem('ngoId') || '');
  const [data, setData] = useState(null);

  const load = async () => {
    if (!ngoId) return;
    try {
      const res = await approvalsApi.ngoApprovals(ngoId);
      setData(res.data || res);
    } catch (err) {
      console.error(err);
      alert('Failed to load approvals');
    }
  };

  useEffect(() => { load(); }, [ngoId]);

  const handleCreate = async (e) => {
    e.preventDefault();
    const tokenId = e.target.tokenId.value;
    const amount = e.target.amount.value;
    const note = e.target.note.value;
    const createdBy = window.localStorage.getItem('userCert') || 'ngoUser';

    try {
      await approvalsApi.create({ createdBy, tokenId, ngoId, amount, note });
      e.target.reset();
      await load();
      alert('Approval requested');
    } catch (err) {
      console.error(err);
      alert('Failed to create approval');
    }
  };

  return (
    <div>
      <PageHeader title="Approvals (NGO)" />
      <div style={{ marginBottom: 20 }}>
        <form onSubmit={handleCreate}>
          <div>
            <label>NGO Id</label>
            <input name="ngoId" value={ngoId} onChange={(e) => setNgoId(e.target.value)} required />
          </div>
          <div>
            <label>Token Id</label>
            <input name="tokenId" required />
          </div>
          <div>
            <label>Amount</label>
            <input name="amount" type="number" step="0.01" required />
          </div>
          <div>
            <label>Note</label>
            <input name="note" />
          </div>
          <div>
            <button type="submit">Request Approval</button>
          </div>
        </form>
      </div>

      <div>
        <h3>Summary</h3>
        {data ? (
          <div>
            <div>Approved: {data.totals.approvedAmount} ({data.totals.approvedCount})</div>
            <div>Pending: {data.totals.pendingAmount} ({data.totals.pendingCount})</div>
            <div>Failed: {data.totals.failedCount}</div>
          </div>
        ) : (
          <div>No data</div>
        )}

        <h4>All approvals</h4>
        <div>
          {data && data.approvals && data.approvals.length ? (
            <table style={{ width: '100%' }}>
              <thead>
                <tr><th>Id</th><th>Token</th><th>Amount</th><th>Status</th><th>Created</th></tr>
              </thead>
              <tbody>
                {data.approvals.map((a) => (
                  <tr key={a.approvalId}><td>{a.approvalId}</td><td>{a.tokenId}</td><td>{a.amount}</td><td>{a.status}</td><td>{a.createdAt}</td></tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div>No approvals yet</div>
          )}
        </div>
      </div>
    </div>
  );
}
